package main

import "fmt"

type Stack struct{ items []int }

func (s Stack) Push(v int) { s.items = append(s.items, v) }

func main() {
	var s Stack
	s.Push(1)
	s.Push(2)
	fmt.Println(len(s.items))
}

package main

import (
	"fmt"
	"sync"
)

type SafeCounter struct {
	mu sync.Mutex
	n  int
}

func (c SafeCounter) Inc() {
	c.mu.Lock()
	c.n++
	c.mu.Unlock()
}

func main() {
	var c SafeCounter
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}
	wg.Wait()
	fmt.Println(c.n)
}
